"""Independent reference model of PROTOCOL.md (v4.0): LPM, compact image
construction with randomized-but-legal placement, and full semantic image
validation.  Used only for testing; not collected with src/."""
import random

NULL_MARK = 4194303
HOP_MAX = 4194302

# ---------- bit helpers ----------
def field(word, pos, n):
    return (word >> pos) & ((1 << n) - 1)

def put(word, pos, n, v):
    assert 0 <= v < (1 << n), (v, n)
    return word | (v << pos)

def bits(hi, lo, start, count):
    v = 0
    for i in range(count):
        b = start + i
        bit = (hi >> (63 - b)) & 1 if b < 64 else (lo >> (127 - b)) & 1
        v = (v << 1) | bit
    return v

def set_bits(hi, lo, start, count, v):
    for i in range(count):
        bit = (v >> (count - 1 - i)) & 1
        if bit:
            if start + i < 64: hi |= 1 << (63 - (start + i))
            else: lo |= 1 << (127 - (start + i))
    return hi, lo

def norm(hi, lo, length):
    if length >= 64:
        keep = 64 - (length - 64)
        return hi, (lo >> keep) << keep if keep else lo
    keep = 64 - length
    return ((hi >> keep) << keep if keep else hi), 0

# ---------- LPM model ----------
class Fib:
    def __init__(self):
        self.d = {}
    def put(self, hi, lo, length, hop):
        self.d[norm(hi, lo, length) + (length,)] = hop
    def lookup_upto(self, hi, lo, maxlen=128):
        best = None
        for (h, l, ln), hop in self.d.items():
            if ln > maxlen: continue
            if bits(hi, lo, 0, ln) == bits(h, l, 0, ln):
                if best is None or ln > best[0]: best = (ln, hop)
        return None if best is None else best[1]
    def prefixes(self):
        return sorted([(h, l, ln, hop) for (h, l, ln), hop in self.d.items()], key=lambda x: (x[2], x[0], x[1]))

# ---------- structure ----------
OWNER = {0: (0, 16), 16: (17, 64), 64: (65, 128)}

def owner_of(length):
    return 0 if length <= 16 else (16 if length <= 64 else 64)

class Node:
    __slots__ = ('origin', 'depth', 'rhi', 'rlo', 'own', 'kids', 'type', 'height', 'stage',
                 'bulk', 'bulk_stage', 'direct', 'cell', 'size')
    def __init__(self):
        self.kids = []
        self.own = []
        self.bulk = []
        self.direct = []

def build(origin, depth, rhi, rlo, pfx):
    n = Node()
    n.origin, n.depth, n.rhi, n.rlo = origin, depth, rhi, rlo
    if len(pfx) <= 2:
        n.type = 4 if len(pfx) == 1 else 5
        n.own = list(pfx)
        return n
    local, kids = [], {}
    for p in pfx:
        if p[2] <= depth + 5: local.append(p)
        else: kids.setdefault(bits(p[0], p[1], depth, 6), []).append(p)
    n.own = local
    for k in sorted(kids):
        hi, lo = set_bits(rhi, rlo, depth, 6, k)
        n.kids.append((k, build(origin, depth + 6, hi, lo, kids[k])))
    n.type = 1 if len(n.kids) <= 2 else (2 if len(n.kids) <= 6 else 3)
    return n

def calc(n, rng):
    for _, c in n.kids: calc(c, rng)
    if n.type == 3:
        k = len(n.kids)
        nd = min(3, k - 4)
        if rng is not None and k - 4 >= 0:
            nd = rng.randint(0, min(3, k - 4))
        n.direct = n.kids[:nd]
        n.bulk = n.kids[nd:]
        bs = max(c.height for _, c in n.bulk)
        if rng is not None:
            hi_lim = max([c.height for _, c in n.direct] + [bs])
            bs = rng.randint(bs, hi_lim)
        n.bulk_stage = bs
    h = 0
    for _, c in n.direct: h = max(h, c.height + 1)
    if n.type == 3 and n.bulk: h = max(h, n.bulk_stage + 1)
    n.height = h
    return n

def stages(n, stage, rng):
    if rng is None or stage > n.height:
        n.stage = stage
    else:
        n.stage = rng.randint(n.height, stage) if False else n.height
    if n.type == 3 and n.bulk:
        # bulk stage must stay strictly below the node stage
        cap = n.stage - 1
        lo = max(c.height for _, c in n.bulk)
        if lo > cap:
            n.stage = lo + 1
        n.bulk_stage = rng.randint(max(lo, 0), n.stage - 1) if rng is not None else lo
    for _, c in n.direct: stages(c, c.height if rng is None else max(c.height, rng.randint(c.height, n.stage - 1)) if n.stage > c.height else c.height, rng)
    if n.type == 3 and n.bulk:
        for _, c in n.bulk: stages(c, n.bulk_stage, rng)

def collect(n, out):
    out.append(n)
    for _, c in n.kids: collect(c, out)

def layout(nodes, rng):
    """Assign cells per stage; returns cells list."""
    units = [[] for _ in range(11)]   # list of blocks (list of nodes) needing 2 cells each
    halves = [[] for _ in range(11)]
    bulkset = set()
    for n in nodes:
        if n.type == 3 and n.bulk:
            blk = [c for _, c in n.bulk]
            for c in blk: bulkset.add(id(c))
            units[n.bulk_stage].append(blk)
    for n in nodes:
        if id(n) in bulkset: continue
        if n.type in (1, 4): halves[n.stage].append(n)
        else: units[n.stage].append([n])
    cells = [0] * 11
    for s in range(11):
        if rng: rng.shuffle(units[s]); rng.shuffle(halves[s])
        c = 0
        for blk in units[s]:
            for x in blk:
                x.cell = c; c += 2
                x.size = 2
        c = 0
        # two-cell items always start on even cells; halves pair up afterwards
        pos = 0
        for blk in units[s]:
            for x in blk:
                x.cell = pos; pos += 2
        for x in halves[s]:
            x.cell = pos; pos += 1
        cells[s] = pos
    return cells

def pattern_of(n, pfx=None):
    pat = 0
    ni = []
    for p in n.own:
        l = p[2] - n.depth
        v = bits(p[0], p[1], n.depth, l)
        pos = (1 << l) + v
        pat |= 1 << pos
        ni.append((pos, p[3]))
    ni.sort()
    return pat, [h for _, h in ni]

def build_image(prefixes, rng=None):
    """prefixes: list of (hi, lo, len, hop)."""
    g0 = [p for p in prefixes if p[2] <= 16]
    g16 = {}
    g64 = {}
    for p in prefixes:
        if owner_of(p[2]) == 16: g16.setdefault(p[0] >> 48, []).append(p)
        elif owner_of(p[2]) == 64: g64.setdefault(p[0], []).append(p)
    roots = []
    if g0: roots.append(build(0, 0, 0, 0, sorted(g0)))
    f16 = []
    for k in sorted(g16):
        r = build(16, 16, k << 48, 0, sorted(g16[k])); roots.append(r); f16.append((k, r))
    f64 = []
    for k in sorted(g64):
        r = build(64, 64, k, 0, sorted(g64[k])); roots.append(r); f64.append((k, r))
    fib = Fib()
    for p in prefixes: fib.d[(p[0], p[1], p[2])] = p[3]
    for r in roots:
        calc(r, rng)
        stages(r, r.height, rng)
    nodes = []
    for r in roots: collect(r, nodes)
    cells = layout(nodes, rng)
    pats = {}
    ni_all = []
    order = list(nodes)
    if rng: rng.shuffle(order)
    for n in nodes:
        if n.type in (4, 5):
            n.pat, n.nilist = None, None
            n.ni = None
        else:
            pat, nilist = pattern_of(n)
            n.pat, n.nilist = pat, nilist
            pats[pat] = True
    bm = sorted(pats)
    bmid = {p: i for i, p in enumerate(bm)}
    nislice = {}
    nxt = []
    for n in order:
        if n.type in (4, 5) or not n.nilist: continue
        if any(m.nilist == n.nilist and m.pat == n.pat and id(m) != id(n) and id(m) < id(n) for m in order):
            pass
        if id(n) not in nislice:
            nislice[id(n)] = len(nxt)
            nxt.extend(n.nilist)
    banks = [[0] * ((c + 1) // 2) for c in cells]
    for n in nodes:
        half = n.type in (1, 4)
        off = 0 if not half else (128 if n.cell % 2 else 0)
        w = 0
        w = put(w, 0, 3, n.type)
        bmp = fib.lookup_upto(n.rhi, n.rlo, n.depth)
        w = put(w, 3, 22, NULL_MARK if bmp is None else bmp)
        if n.type in (4, 5):
            pos = 25
            for p in n.own:
                frag = p[0] if n.origin == 0 else ((p[0] << 16) if n.origin == 16 else p[1])
                w = put(w, pos, 64, frag)
                w = put(w, pos + 64, 8, p[2] - n.origin)
                w = put(w, pos + 72, 22, p[3])
                pos += 94
        else:
            w = put(w, 25, 16, bmid[n.pat])
            w = put(w, 41, 22, nislice.get(id(n), 0))
            if n.type == 3:
                bmp64 = 0
                for k, c in n.bulk: bmp64 |= 1 << k
                base = min(c.cell for _, c in n.bulk)
                w = put(w, 63, 64, bmp64)
                w = put(w, 127, 22, base)
                w = put(w, 149, 4, n.bulk_stage)
                pos = 153
                for i in range(3):
                    if i < len(n.direct):
                        k, c = n.direct[i]
                        v = k | (c.stage << 6) | (c.cell << 10)
                    else:
                        v = 15 << 6
                    w = put(w, pos, 32, v); pos += 32
            else:
                pos = 63
                want = 2 if n.type == 1 else 6
                for i in range(want):
                    if i < len(n.kids):
                        k, c = n.kids[i]
                        v = k | (c.stage << 6) | (c.cell << 10)
                    else:
                        v = 15 << 6
                    w = put(w, pos, 32, v); pos += 32
        banks[n.stage][n.cell // 2] ^= (w << off)
    img = {
        'root': None,
        'front16': [],
        'front64': [],
        'cells': cells,
        'banks': [[format(x, '064x') for x in b] for b in banks],
        'bitmaps': [format(x, '016x') for x in bm],
        'nexthops': nxt,
    }
    if g0:
        r = roots[0]
        img['root'] = [r.stage, r.cell]
    for k, r in f16: img['front16'].append([format(k, '04x'), r.stage, r.cell])
    for k, r in f64: img['front64'].append([format(k, '016x'), r.stage, r.cell])
    return img

# ---------- independent validation ----------
class Bad(Exception): pass

def validate(img):
    """Return dict {(hi,lo,len):hop} when the image is fully valid, else raise Bad."""
    keys = set(img)
    if keys != set('root front16 front64 cells banks bitmaps nexthops'.split()): raise Bad('keys')
    cells = img['cells']; banks = img['banks']
    if len(cells) != 11 or len(banks) != 11: raise Bad('count')
    for s in range(11):
        if not isinstance(cells[s], int) or not 0 <= cells[s] <= 131072: raise Bad('cells')
        if len(banks[s]) != (cells[s] + 1) // 2: raise Bad('rows')
    if sum(len(b) for b in banks) > 65536: raise Bad('row bound')
    if len(img['bitmaps']) > 8193 or len(img['nexthops']) > 8192: raise Bad('side bound')
    bm = [int(x, 16) for x in img['bitmaps']]
    if any(bm[i] <= bm[i-1] for i in range(1, len(bm))): raise Bad('bitmap order')
    ni = img['nexthops']
    if any(not isinstance(x, int) or not 0 <= x <= HOP_MAX for x in ni): raise Bad('ni hop')
    word = lambda s, r: int(banks[s][r], 16)

    used_cell = [[False] * c for c in cells]
    prefixes = {}
    nodes = []   # (depth, origin, rhi, rlo, bmp, own, edges)

    def take(s, c, cnt, owner):
        if c + cnt > cells[s]: raise Bad('range')
        for x in range(c, c + cnt):
            if used_cell[s][x]: raise Bad('overlap')
            used_cell[s][x] = True

    def walk(s, c, origin, depth, rhi, rlo, parent_stage, bulk_child):
        if not 0 <= s <= 10: raise Bad('stage')
        if c >= cells[s]: raise Bad('cell')
        if bulk_child and c % 2: raise Bad('bulk align')
        off = 128 if c % 2 else 0
        w = word(s, c // 2)
        t = field(w, off, 3)
        if t not in (1, 2, 3, 4, 5): raise Bad('type')
        size = 1 if t in (1, 4) else 2
        if bulk_child: size = 2
        if size == 2 and c % 2: raise Bad('align')
        if size == 2 and field(w, 128, 128) != 0 and off == 0:
            pass
        take(s, c, size, None)
        if bulk_child and size == 2 and t in (1, 4):
            if field(w, 128, 128) != 0: raise Bad('bulk pad')
        bmp = field(w, off + 3, 22)
        omin, omax = OWNER[origin]
        own = []
        edges = []
        if t in (4, 5):
            cnt = 1 if t == 4 else 2
            pos = off + 25
            seen = set()
            for i in range(cnt):
                frag = field(w, pos, 64); pos += 64
                rl = field(w, pos, 8); pos += 8
                hop = field(w, pos, 22); pos += 22
                if hop > HOP_MAX: raise Bad('hop')
                if origin == 16 and frag >> 48: raise Bad('frag16')
                length = origin + rl
                if length > 128: raise Bad('fraglen')
                if origin == 0: hi, lo = frag, 0
                elif origin == 16: hi, lo = (rhi & (0xFFFF << 48)) | (frag >> 16), 0
                else: hi, lo = rhi, frag
                if norm(hi, lo, length) != (hi, lo): raise Bad('frag host bits')
                if bits(hi, lo, 0, depth) != bits(rhi, rlo, 0, depth): raise Bad('inline region')
                if length < depth: raise Bad('inline depth')
                if not omin <= length <= omax: raise Bad('inline owner')
                if (hi, lo, length) in seen: raise Bad('dup inline')
                seen.add((hi, lo, length))
                own.append((hi, lo, length, hop))
            rsv = 9 if t == 4 else 43
            if field(w, off + (119 if t == 4 else 213), rsv) != 0: raise Bad('reserved')
        else:
            bid = field(w, off + 25, 16)
            base = field(w, off + 41, 22)
            if bid >= len(bm): raise Bad('bitmap id')
            pat = bm[bid]
            if pat & 1: raise Bad('bit0')
            k = bin(pat).count('1')
            if k == 0:
                if base != 0: raise Bad('empty base')
            elif base + k > len(ni): raise Bad('ni range')
            slot = 0
            for p in range(1, 64):
                if not (pat >> p) & 1: continue
                l = p.bit_length() - 1
                v = p - (1 << l)
                length = depth + l
                hi, lo = set_bits(rhi, rlo, depth, l, v)
                if not omin <= length <= omax: raise Bad('ni owner')
                hop = ni[base + slot]; slot += 1
                own.append((hi, lo, length, hop))
            if slot != k: raise Bad('ni count')
            if t == 3:
                bb = field(w, off + 63, 64)
                bbase = field(w, off + 127, 22)
                bstage = field(w, off + 149, 4)
                nb = bin(bb).count('1')
                if nb < 4: raise Bad('bulk count')
                if bstage > 10 or bstage >= s: raise Bad('bulk stage')
                if bbase % 2: raise Bad('bulk base')
                if bbase + 2 * nb > cells[bstage]: raise Bad('bulk range')
                rank = 0
                for p in range(64):
                    if (bb >> p) & 1:
                        edges.append((p, bstage, bbase + 2 * rank, True)); rank += 1
                pos = off + 153
                prev = -1
                absent = False
                for i in range(3):
                    v = field(w, pos, 32); pos += 32
                    if v == (15 << 6): absent = True; continue
                    if absent: raise Bad('child order')
                    st = (v >> 6) & 15
                    if st > 10: raise Bad('child stage')
                    k6 = v & 63
                    if (bb >> k6) & 1: raise Bad('key clash')
                    if k6 <= prev: raise Bad('child sort')
                    prev = k6
                    edges.append((k6, st, (v >> 10) & ((1 << 22) - 1), False))
                if field(w, off + 249, 7) != 0: raise Bad('reserved')
            else:
                pos = off + 63
                slots = 2 if t == 1 else 6
                prev = -1
                absent = False
                present = 0
                for i in range(slots):
                    v = field(w, pos, 32); pos += 32
                    if v == (15 << 6): absent = True; continue
                    if absent: raise Bad('child order')
                    st = (v >> 6) & 15
                    if st > 10: raise Bad('child stage')
                    k6 = v & 63
                    if k6 <= prev: raise Bad('child sort')
                    prev = k6
                    edges.append((k6, st, (v >> 10) & ((1 << 22) - 1), False))
                    present += 1
                if t == 1 and present > 2: raise Bad('type1 children')
                if t == 2 and not 3 <= present <= 6: raise Bad('type2 children')
                rsv_pos = 127 if t == 1 else 255
                if field(w, off + rsv_pos, 1) != 0: raise Bad('reserved')
        total = len(own)
        keys_seen = set()
        for p in own:
            key = p[:3]
            if key in keys_seen: raise Bad('dup own')
            keys_seen.add(key)
        for (k6, cs, cc, isbulk) in edges:
            if cs >= s: raise Bad('stage descent')
            chi, clo = set_bits(rhi, rlo, depth, 6, k6)
            total += walk(cs, cc, origin, depth + 6, chi, clo, s, isbulk)
        if prev != -1:
            pass
        # child keys must be globally unique and sorted after merge
        kk = [e[0] for e in edges]
        if len(set(kk)) != len(kk): raise Bad('duplicate child key')
        if t == 3 and not 7 <= len(edges) <= 64: raise Bad('type3 children')
        if t == 4 and total != 1: raise Bad('type4 size')
        if t == 5 and total != 2: raise Bad('type5 size')
        if t in (1, 2, 3) and total < 3: raise Bad('node size')
        nodes.append((s, c, depth, origin, rhi, rlo, bmp))
        for p in own:
            key = p[:3]
            if key in prefixes: raise Bad('duplicate prefix')
            prefixes[key] = p[3]
        return total

    root = img['root']
    if root is not None:
        if not (isinstance(root, list) and len(root) == 2): raise Bad('root shape')
        walk(root[0], root[1], 0, 0, 0, 0, 99, False)
    prev = -1
    for e in img['front16']:
        k = int(e[0], 16)
        if len(e[0]) != 4 or k <= prev: raise Bad('front16 order')
        prev = k
        walk(e[1], e[2], 16, 16, k << 48, 0, 99, False)
    prev = -1
    for e in img['front64']:
        k = int(e[0], 16)
        if len(e[0]) != 16 or k <= prev: raise Bad('front64 order')
        prev = k
        walk(e[1], e[2], 64, 64, k, 0, 99, False)
    for s in range(11):
        if not all(used_cell[s]): raise Bad('dense')
        if cells[s] % 2 and field(word(s, len(banks[s]) - 1), 128, 128) != 0: raise Bad('pad')
    if len(prefixes) > 8192: raise Bad('fib size')
    # dictionary usage
    used_pat = set()
    spans = []
    # recompute per node patterns/NI from the record again (cheap duplicate check)
    fib = Fib()
    for (hi, lo, length), hop in prefixes.items(): fib.put(hi, lo, length, hop)
    for (s, c, depth, origin, rhi, rlo, bmp) in nodes:
        want = fib.lookup_upto(rhi, rlo, depth)
        want = NULL_MARK if want is None else want
        if bmp != want: raise Bad('bmp')
    # every bitmap used / every NI entry used
    seen_ids = set()
    for (s, c, depth, origin, rhi, rlo, bmp) in nodes:
        w = word(s, c // 2)
        off = 128 if c % 2 else 0
        t = field(w, off, 3)
        if t in (4, 5): continue
        bid = field(w, off + 25, 16)
        seen_ids.add(bid)
    if seen_ids != set(range(len(bm))): raise Bad('bitmap unused')
    cover = [0] * len(ni)
    for (s, c, depth, origin, rhi, rlo, bmp) in nodes:
        w = word(s, c // 2)
        off = 128 if c % 2 else 0
        t = field(w, off, 3)
        if t in (4, 5): continue
        bid = field(w, off + 25, 16)
        base = field(w, off + 41, 22)
        k = bin(bm[bid]).count('1')
        if k == 0: continue
        for x in range(base, base + k):
            if x >= len(ni) or cover[x]: raise Bad('ni overlap')
            cover[x] = 1
    if len(ni) and not all(cover): raise Bad('ni holes')
    # fronts complete
    need16 = set(hi >> 48 for (hi, lo, l) in prefixes if 17 <= l <= 64)
    need64 = set(hi for (hi, lo, l) in prefixes if l >= 65)
    got16 = set(int(e[0], 16) for e in img['front16'])
    got64 = set(int(e[0], 16) for e in img['front64'])
    if need16 != got16 or need64 != got64: raise Bad('fronts complete')
    if (root is not None) != any(l <= 16 for (hi, lo, l) in prefixes): raise Bad('root present')
    return prefixes

def lpm_of(prefixes, hi, lo):
    best = None
    for (h, l, ln), hop in prefixes.items():
        if bits(hi, lo, 0, ln) == bits(h, l, 0, ln):
            if best is None or ln > best[0]: best = (ln, hop)
    return None if best is None else best[1]
